// The pull request's checks for obid-spec's autofix workflows: red at the first head obid's
// view saw (kept in red-at), green at any later head; with always-red here, red at every head.
const fs = require("fs");
const { execFileSync } = require("child_process");
const [what, ...args] = process.argv.slice(2);
const view = JSON.parse(execFileSync("node", ["pull-request.js", "view", ...args], { encoding: "utf8" }));
if (!fs.existsSync("red-at") && view.headRefOid) fs.writeFileSync("red-at", view.headRefOid);
const red = view.state === "OPEN" && (fs.existsSync("always-red") ||
  (fs.existsSync("red-at") && fs.readFileSync("red-at", "utf8") === view.headRefOid));
if (what === "view") {
  if (red) {
    view.statusCheckRollup = [{ __typename: "CheckRun", name: "test", status: "COMPLETED", conclusion: "FAILURE" }];
    view.mergeStateStatus = "UNSTABLE";
  }
  process.stdout.write(JSON.stringify(view) + "\n");
} else if (what === "failed") {
  process.stdout.write(JSON.stringify(red ? [{ databaseId: 41 }] : []) + "\n");
} else if (what === "all") {
  process.stdout.write(JSON.stringify(red ? [{ databaseId: 41, conclusion: "failure" }] : []) + "\n");
}

